import json
import sys
import time
import hashlib
from datetime import datetime

def parse_token(token):
    parts = token.split('.')
    if len(parts) != 3:
        return None
    payload = parts[1]
    try:
        decoded_payload = json.loads(base64url_decode(payload))
        username = decoded_payload.get('username')
        expires = decoded_payload.get('expires')
        key = decoded_payload.get('key')
        return username, expires, key
    except:
        return None

def base64url_decode(s):
    import base64
    padding = len(s) % 4
    if padding:
        s += '=' * (4 - padding)
    return base64.urlsafe_b64decode(s)

def generate_token(username, expires, key):
    payload = {
        'username': username,
        'expires': expires,
        'key': key
    }
    payload_str = json.dumps(payload)
    payload_bytes = payload_str.encode('utf-8')
    payload_hash = hashlib.sha256(payload_bytes).hexdigest()
    encoded_payload = base64url_encode(payload_hash)
    encoded_header = base64url_encode('payload')
    return f"{encoded_header}.{encoded_payload}"

def base64url_encode(s):
    import base64
    padding = len(s) % 4
    s += '=' * (4 - padding)
    return base64.urlsafe_b64encode(s).decode('utf-8')

def main():
    with open('users.json') as f:
        users = json.load(f)

    if len(sys.argv) == 4 and sys.argv[1] == 'issue':
        username = sys.argv[2]
        expires = int(sys.argv[3])
        current_key = sys.argv[4] if len(sys.argv) > 4 else None
        if username not in users:
            sys.exit(1)
        token = generate_token(username, expires, sys.argv[4])
        print(token)
    elif len(sys.argv) == 3 and sys.argv[1] == 'check':
        token = sys.argv[2]
        username, expires, key = parse_token(token)
        if not username or not expires or not key:
            sys.exit(1)
        if key != sys.argv[4]:
            sys.exit(1)
        if username not in users:
            sys.exit(1)
        current_time = int(time.time())
        if expires <= current_time:
            sys.exit(1)
        role = users[username]
        print(f"{username} {role}")
    else:
        sys.exit(1)

if __name__ == "__main__":
    main()
